_RESULT_WORDS = {"winner", "won", "wins", "lost", "losses", "score", "placement", "seed", "rank", "record", "dq"}
_TOOLS = [
    tools.find_players,
    tools.get_player_usage,
    tools.get_head_to_head,
    tools.find_tournaments,
    tools.get_event_entrants,
]


def _answers(monkeypatch, name: str, value, module=None) -> dict:
    """Patch an async data function to return `value` (or raise it); records its arguments"""
    seen = {}

    async def fake(*args, **kwargs):
        seen.update(kwargs, args=args)
        if isinstance(value, Exception):
            raise value
        return value

    monkeypatch.setattr(module or tools.derived, name, fake)
    return seen


def _result_names(names) -> set[str]:
    return {name for name in names if _RESULT_WORDS & set(name.lower().split("_"))}


def _lookup(tag: str, player_id: int) -> PlayerLookup:
    return PlayerLookup(query=tag, match_type="tag_exact", player_id=player_id, tag=tag)


def _h2h() -> HeadToHead:
    game = MatchupGame(number=1, character_1="Cloud", character_2="Steve", stage="Battlefield", winner=1)
    sets = [
        MatchupSet(
            date=dt.date(2026, 5, 5),
            tournament="Kagaribi",
            event="Singles",
            event_slug="tournament/k/event/s",
            round="Winners Final",
            online=False,
            games=[game, game.model_copy(update={"number": 2, "winner": 2})],
            winner=1,
            score_1=3,
            score_2=1,
            seed_1=1,
            seed_2=2,
        ),
        MatchupSet(date=dt.date(2025, 3, 31), tournament="BoBC", event="Main", event_slug="t", games=[], winner=2),
    ]
    return HeadToHead(
        player_1=_lookup("Sparg0", 1), player_2=_lookup("acola", 2), sets=sets, sets_won_1=1, sets_won_2=1, capped=False
    )


# --- the rule: no results reach the agent -----------------------------------------------


def test_the_capability_has_exactly_these_tools():
    registered = {tool.name for tool in tools.startgg_capability.tools}
    assert registered == {function.__name__ for function in _TOOLS}
    assert not _result_names(registered)


@pytest.mark.parametrize("function", _TOOLS, ids=lambda f: f.__name__)
def test_no_tool_takes_or_returns_a_result_field(function):
    tool = Tool(function, include_return_schema=True)
    parameters = tool.tool_def.parameters_json_schema.get("properties", {})
    assert not _result_names(parameters)
    schema = tool.tool_def.return_schema or {}
    fields = set(schema.get("properties", {}))
    for definition in schema.get("$defs", {}).values():
        fields |= set(definition.get("properties", {}))
    assert not _result_names(fields)


def test_tables_have_no_result_columns(monkeypatch):
    _answers(monkeypatch, "head_to_head", _h2h())
    h2h = tools.get_head_to_head("Sparg0", "acola").to_df()
    assert h2h.columns == [
        "date",
        "tournament",
        "event",
        "round",
        "online",
        "game",
        "Sparg0_character",
        "acola_character",
        "stage",
    ]
    # two games of the first set, then one empty row for the set reported without games
    assert h2h["game"].to_list() == [1, 2, None]
    assert h2h["Sparg0_character"].to_list() == ["Cloud", "Cloud", None]

    event = Event(id=5, name="Singles", slug="tournament/k/event/s")
    entrant = Entrant(
        id=1, name="FaZe | Sparg0", players=[Player(id=1, tag="Sparg0", prefix="FaZe")], seed=1, placement=1
    )
    page = EntrantsPage(event=event, page_info=PageInfo(total=300), entrants=[entrant])
    _answers(monkeypatch, "event_entrants", page, module=startgg)
    entrants = tools.get_event_entrants("tournament/k/event/s")
    assert entrants.to_df().columns == ["tag", "prefix", "player_id", "entrant"]
    assert (entrants.rows, entrants.total_rows, entrants.truncated) == (1, 300, True)


def test_results_module_is_never_imported():
    """ds.data.startgg.results is Python-only; the agent module must not reach it"""
    tree = ast.parse(inspect.getsource(tools))
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            imported |= {node.module or ""} | {f"{node.module}.{alias.name}" for alias in node.names}
        elif isinstance(node, ast.Import):
            imported |= {alias.name for alias in node.names}
    assert not {name for name in imported if "results" in name}
    assert not hasattr(tools.derived, "player_results")


def test_agent_uses_startgg_instead_of_supermajor():
    source = inspect.getsource(sys.modules["ds.ai.agent"])
    assert "startgg_capability," in source
    assert "from ds.ai.supermajor" not in source


