def test_find_players_caps_results(monkeypatch):
    many = [PlayerCandidate(player_id=i, tag="Luke") for i in range(40)]
    _answers(monkeypatch, "find_players", many)
    assert len(tools.find_players("Luke")) == tools.MAX_PLAYERS


def test_usage_resolves_the_character(monkeypatch):
    seen = _answers(monkeypatch, "player_usage", "usage")
    validator = Tool(tools.get_player_usage).function_schema.validator

    def call(**arguments):
        """Call the tool the way pydantic-ai does: arguments through its validator first"""
        return tools.get_player_usage(**validator.validate_python(arguments))

    assert call(player="Sparg0", vs_characters=["Little Mac"]) == "usage"
    assert (seen["args"], seen["vs_characters"]) == (("Sparg0",), [CharGroup.LITTLE_MAC])
    call(player="Sparg0", vs_characters=["steve", "Pac-Man"])  # several: games against any of them
    assert seen["vs_characters"] == [CharGroup.STEVE, CharGroup.PAC_MAN]
    assert (seen["setting"], seen["requests"]) == ("all", 1)  # 30 sets: one request
    call(player="Sparg0", sets=90)
    assert seen["requests"] == 3  # each 30 sets is one start.gg request
    with pytest.raises(ValidationError, match="sets"):  # only whole requests' worth, up to 150
        call(player="Sparg0", sets=45)
    with pytest.raises(ValidationError, match="sets"):
        call(player="Sparg0", sets=300)
    tools.get_player_usage("Sparg0", setting="offline")
    assert seen["setting"] == "offline"
    # the character type parses what the model writes: a name, a group member, part of a name
    for written in ("Pokemon Trainer", "pt_ivysaur", "squirtle"):
        call(player="Sparg0", vs_characters=[written])
        assert seen["vs_characters"] == [CharGroup.POKEMON_TRAINER]
    call(player="Sparg0")
    assert seen["vs_characters"] is None
    with pytest.raises(ValidationError, match="vs_characters"):  # pydantic-ai turns this into a retry
        call(player="Sparg0", vs_characters=["steve", "Goku"])
    # the model sees the allowed picks in the tool's schema
    schema = Tool(tools.get_player_usage).tool_def.parameters_json_schema
    assert schema["$defs"]["CharGroup"]["enum"] == [pick.value for pick in CharGroup]
    # the window is the newest sets, a choice the model sees with its allowed values
    assert set(schema["properties"]) == {"player", "vs_characters", "setting", "sets"}
    assert schema["properties"]["sets"]["enum"] == [30, 60, 90, 120, 150]


def test_unknown_player_asks_the_model_to_retry(monkeypatch):
    _answers(monkeypatch, "player_usage", PlayerLookupError("no player tagged 'Nobody'; similar tags: none"))
    with pytest.raises(ModelRetry, match="find_players"):
        tools.get_player_usage("Nobody")


@pytest.mark.parametrize(
    ("error", "match"),
    [
        (startgg.RateLimitError("start.gg rate limit hit: at most 80 requests per 60 s per token"), "80 requests"),
        (startgg.MissingTokenError("no start.gg API token stored"), "no start.gg API token"),
        (httpx2.ConnectError("refused"), "could not be reached"),
    ],
)
def test_site_failures_are_final_not_retries(monkeypatch, error, match):
    _answers(monkeypatch, "player_usage", error)
    with pytest.raises(ToolFailed, match=match):
        tools.get_player_usage("Sparg0")


def test_find_tournaments(monkeypatch):
    event = Event(id=5, name="Ultimate Singles", slug="tournament/genesis/event/ultimate-singles", num_entrants=900)
    genesis = Tournament(
        id=1,
        name="Genesis",
        slug="tournament/genesis",
        start_at=dt.datetime(2027, 1, 20, tzinfo=dt.UTC),
        city="San Jose",
        state="CA",
        country="US",
        events=[event, event.model_copy(update={"name": "Squad Strike"})],
    )
    page = TournamentsPage(page_info=PageInfo(total=40), tournaments=[genesis])
    seen = _answers(monkeypatch, "tournaments", page, module=startgg)
    table = tools.find_tournaments(name="Gen", country="us", state="ca", after="2027-01-01")
    assert (seen["country"], seen["state"], seen["upcoming"]) == ("US", "CA", True)
    assert seen["after"] == dt.datetime(2027, 1, 1, tzinfo=dt.UTC)
    assert seen["before"] is None
    frame = table.to_df()
    assert frame["event"].to_list() == ["Ultimate Singles", "Squad Strike"]
    assert frame["event_url"][0] == "https://www.start.gg/tournament/genesis/event/ultimate-singles"
    assert not _result_names(frame.columns)
    assert table.truncated  # 40 matched, one page fetched
    with pytest.raises(ModelRetry, match="at least one"):
        tools.find_tournaments()
    with pytest.raises(ModelRetry, match="must be a date"):
        tools.find_tournaments(country="US", after="next week")


def test_bad_event_asks_the_model_to_retry():
    with pytest.raises(ModelRetry, match="not an event"):
        tools.get_event_entrants("https://www.start.gg/tournament/genesis")
